import java.util.List;

/**
 * A simple model of a Deer.
 * Deers age, move, eat grass, breed, and die.
 *
 * @version 2022.03.02 
 */
public class Deer extends Animal
{
    // Characteristics shared by all Deers (class variables).

    // The age at which a Deer can start to breed.
    private static final int BREEDING_AGE = 10;
    // The age to which a Deer can live.
    private static final int MAX_AGE = 175;
    // The likelihood of a Deer breeding.
    private static final double BREEDING_PROBABILITY = 0.10;
    // The maximum number of births.
    private static final int MAX_LITTER_SIZE = 5;
    // The food value of a single dear. In effect, this is the
    // number of steps it can go.
    private static final int FOOD_VALUE = 50;
    // The default food value of a single deer.
    private static final int DEFAULT_FOOD_LEVEL = 250;

    /**
     * Create a new Deer. A Deer may be created with age
     * zero (a new born) or with a random age.
     * 
     * @param randomAge If true, the Deer will have a random age.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Deer(boolean randomAge, Field field, Location location)
    {
        super(field, location);
        initializeAge(randomAge, MAX_AGE);
        initializeFoodLevel(randomAge, DEFAULT_FOOD_LEVEL, DEFAULT_FOOD_LEVEL);
    }

    /**
     * This is what the Deer does most of the time - it runs 
     * around. Sometimes it will breed or die of old age.
     * @param newDeers A list to return newly born Deers.
     * @param step The current simulation step.
     */
    public void act(List<Animal> newDeers, SimulationStep step)
    {
        incrementAge(MAX_AGE);
        decrementFoodLevel();
        updateBurnStatus(step.getWeather());
        if(isAlive()) {
            giveBirth(newDeers);  

            // Move towards a source of food if found.
            Location newLocation;
            if (step.getWeather() == Weather.RAINY) {
                newLocation = null;
            }
            else {
                newLocation = findFood();
            }

            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = freeAdjacentLocation();
            }

            moveToOrDie(newLocation);
        }
    }

    /**
     * Check whether or not this Deer is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newDeers A list to return newly born Deers.
     */
    private void giveBirth(List<Animal> newDeers)
    {
        if(hasAdjacentMate(Deer.class, 2)) {
            addOffspring(newDeers, breed(), (field, location) -> new Deer(false, field, location));
        }
    }

    /**
     * Generate a number representing the number of births,
     * if it can breed.
     * @return The number of births (may be zero).
     */
    private int breed()
    {
        return calculateBirths(BREEDING_AGE, BREEDING_PROBABILITY, MAX_LITTER_SIZE);
    }

    /**
     * Look for grass adjacent to the current location.
     * Only the first live grass is eaten.
     * @return Where food was found, or null if it wasn't.
     */
    private Location findFood()
    {
        return findAdjacentLocation(Grass.class, 1, grass -> {
            if(grass.isAlive()) {
                if(grass.getSize() > 12 && getFoodLevel() < 30) {
                    grass.decrementSize();
                    changeFoodLevel(20);
                }
                return true;
            }
            return false;
        });
    }


    /**
     * @return deer's food value.
     */
    public int foodValue()
    {
        return FOOD_VALUE;
    }
}

import java.util.List;

/**
 * A simple model of a Lion.
 * Lions age, move, eat deers/cats/owls/mouse, and die.
 *
 * @version 2022.03.02 
 */
public class Lion extends Animal
{
    // Characteristics shared by all Liones (class variables).

    // The age at which a Lion can start to breed.
    private static final int BREEDING_AGE = 10;
    // The age to which a Lion can live.
    private static final int MAX_AGE = 225;
    // The likelihood of a Lion breeding. 
    private static final double BREEDING_PROBABILITY = 0.10;
    // The maximum number of births.
    private static final int MAX_LITTER_SIZE = 5;
    // The food value of a single lion.
    private static final int FOOD_VALUE = 20;
    // number of steps a lion can go before it has to eat again.
    private static final int DEFAULT_FOOD_LEVEL = 275;
    // The starting food level for newborn lions.
    private static final int NEWBORN_FOOD_LEVEL = 40;

    /**
     * Create a Lion. A Lion can be created as a new born (age zero
     * and not hungry) or with a random age and food level.
     * 
     * @param randomAge If true, the Lion will have random age and hunger level.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Lion(boolean randomAge, Field field, Location location)
    {
        super(field, location);
        initializeAge(randomAge, MAX_AGE);
        initializeFoodLevel(randomAge, DEFAULT_FOOD_LEVEL, NEWBORN_FOOD_LEVEL);
    }

    /**
     * This is what the Lion does most of the time: it hunts for
     * rabbits. In the process, it might breed, die of hunger,
     * or die of old age.
     * If the weather is foggy, it stops moving.
     * @param newLiones A list to return newly born Liones.
     * @param step The current simulation step.
     */
    public void act(List<Animal> newLions, SimulationStep step)
    {
        incrementAge(MAX_AGE);
        decrementFoodLevel();
        updateBurnStatus(step.getWeather());

        if(isAlive()) {
            giveBirth(newLions);            
            // Move towards a source of food if found.
            Location newLocation;
            if (step.getWeather() == Weather.FOGGY) {
                newLocation = null;
            }
            else {
                newLocation = findFood();
            }
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = freeAdjacentLocation();
            }
            // See if it was possible to move.
            if (!step.isNight()) {
                moveToOrDie(newLocation);
            } 
        }
    }

    /**
     * Look for deer, cat, owl ,mouse adjacent to the current location.
     * Only the first live deer/cat/owl/mouse is eaten.
     * @return Where food was found, or null if it wasn't.
     */
    private Location findFood()
    {
        Location preyLocation = eat(Deer.class);
        if(preyLocation != null) {
            return preyLocation;
        }

        preyLocation = eat(Cat.class);
        if(preyLocation != null) {
            return preyLocation;
        }

        preyLocation = eat(Owl.class);
        if(preyLocation != null) {
            return preyLocation;
        }

        return eat(Mouse.class);
    }

    /**
     * Check whether or not this Lion is to give birth at this step.
     * New births will be made into free adjacent locations of the 24 nearest locations
     * surrounding the Lion.
     * @param newLions A list to return newly born Lions.
     */
    private void giveBirth(List<Animal> newLions)
    {
        if(hasAdjacentMate(Lion.class, 2)) {
            addOffspring(newLions, breed(), (field, location) -> new Lion(false, field, location));
        }
    }

    /**
     * Generate a number representing the number of births,
     * if it can breed.
     * @return The number of births (may be zero).
     */
    private int breed()
    {
        return calculateBirths(BREEDING_AGE, BREEDING_PROBABILITY, MAX_LITTER_SIZE);
    }

    /**
     * Hunt a specific prey species adjacent to this lion.
     */
    private <T extends Animal> Location eat(Class<T> preyClass)
    {
        return findAdjacentLocation(preyClass, 1, prey -> {
            if(prey.isAlive()) {
                prey.setDead();
                changeFoodLevel(prey.foodValue());
                return true;
            }
            return false;
        });
    }

    /**
     * @return lion's food value.
     */
    public int foodValue()
    {
        return FOOD_VALUE;
    }
}

import java.util.List;

/**
 * Shared behavior for predators that hunt mice.
 */
public abstract class MouseHunter extends Animal
{
    private final int breedingAge;
    private final int maxAge;
    private final double breedingProbability;
    private final int maxLitterSize;
    private final int foodValue;

    /**
     * Create a mouse-hunting predator.
     */
    protected MouseHunter(boolean randomAge, Field field, Location location,
                          int breedingAge, int maxAge, double breedingProbability,
                          int maxLitterSize, int defaultFoodLevel, int foodValue)
    {
        super(field, location);
        this.breedingAge = breedingAge;
        this.maxAge = maxAge;
        this.breedingProbability = breedingProbability;
        this.maxLitterSize = maxLitterSize;
        this.foodValue = foodValue;
        initializeAge(randomAge, maxAge);
        initializeFoodLevel(randomAge, defaultFoodLevel, defaultFoodLevel);
    }

    @Override
    public final void act(List<Animal> newAnimals, SimulationStep step)
    {
        incrementAge(maxAge);
        decrementFoodLevel();
        updateBurnStatus(step.getWeather());
        if(isAlive()) {
            addOffspring(newAnimals, calculateBirths(breedingAge, breedingProbability, maxLitterSize),
                         (field, location) -> createYoung(field, location));
            Location newLocation = findFood();
            if(newLocation == null) {
                newLocation = freeAdjacentLocation();
            }
            moveToOrDie(newLocation);
        }
    }

    @Override
    public final int foodValue()
    {
        return foodValue;
    }

    /**
     * Create a newborn of the concrete species.
     */
    protected abstract Animal createYoung(Field field, Location location);

    /**
     * Find and eat an adjacent mouse.
     */
    private Location findFood()
    {
        return findAdjacentLocation(Mouse.class, 1, mouse -> {
            if(mouse.isAlive()) {
                mouse.setDead();
                changeFoodLevel(mouse.foodValue());
                return true;
            }
            return false;
        });
    }
}

import java.util.List;
import java.util.Random;

/**
 * A class representing shared characteristics of animals.
 *
 * @version 2016.02.29 (2)
 */
public abstract class Animal extends Organism
{
    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();

    // The animal's hurt level, when > 3 die
    private int burn;
    // The animal's gender.
    private final Gender gender;
    // The animal's age.
    private int age;
    // The animal's food level.
    private int foodLevel;


    /**
     * Create a new animal at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Animal(Field field, Location location)
    {
        super(field, location);
        burn = 0;
        gender = Gender.random(rand);
    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * @param newAnimals A list to receive newly born animals.
     * @param step The current simulation step.
     */
    abstract public void act(List<Animal> newAnimals, SimulationStep step);

    /**
     * Return the food value this animal provides when eaten.
     */
    abstract public int foodValue();

    /**
     * A factory for creating offspring at a specific location.
     */
    @FunctionalInterface
    protected interface OffspringFactory
    {
        Animal create(Field field, Location location);
    }

    /**
     * update the animal's burn status.
     * @param weather The current weather.
     */
    protected void updateBurnStatus(Weather weather)
    {
        if (burn > 0) {
            if (weather != Weather.RAINY) {
                burn();
            }
            else {
                recover();
            }
        }
    }

    /**
     * animal that step on fire will get burn and if burn status > 3 the animal will die 
     */
    protected void burn()
    {
        burn++;
        if (burn > 3) {
            setDead();
        }
    }

    /**
     * if weather is rainy the animal will recover and reset it's burn status to zero.
     */
    protected void recover()
    {
        burn = 0;
    }

    /**
     * @return the animal's gender
     */
    protected final Gender getGender()
    {
        return gender;
    }

    /**
     * Move to the new location or die if there is nowhere to go.
     */
    protected final void moveToOrDie(Location newLocation)
    {
        if(newLocation != null) {
            setLocation(newLocation);
        }
        else {
            setDead();
        }
    }

    /**
     * Initialize the animal's age.
     */
    protected final void initializeAge(boolean randomAge, int maxAge)
    {
        if(randomAge) {
            age = rand.nextInt(maxAge);
        }
        else {
            age = 0;
        }
    }

    /**
     * Initialize the animal's food level.
     */
    protected final void initializeFoodLevel(boolean randomFoodLevel, int randomUpperBound,
                                             int initialFoodLevel)
    {
        if(randomFoodLevel) {
            foodLevel = rand.nextInt(randomUpperBound);
        }
        else {
            foodLevel = initialFoodLevel;
        }
    }

    /**
     * Increase the animal's age and kill it if it exceeds the limit.
     */
    protected final void incrementAge(int maxAge)
    {
        age++;
        if(age > maxAge) {
            setDead();
        }
    }

    /**
     * Decrease the animal's food level and kill it if depleted.
     */
    protected final void decrementFoodLevel()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * Adjust the animal's food level by the given amount.
     */
    protected final void changeFoodLevel(int delta)
    {
        foodLevel = foodLevel + delta;
    }

    /**
     * Return the animal's age.
     */
    protected final int getAge()
    {
        return age;
    }

    /**
     * Return the animal's food level.
     */
    protected final int getFoodLevel()
    {
        return foodLevel;
    }

    /**
     * Determine how many offspring are produced this step.
     */
    protected final int calculateBirths(int breedingAge, double breedingProbability,
                                        int maxLitterSize)
    {
        if(age >= breedingAge && rand.nextDouble() <= breedingProbability) {
            return rand.nextInt(maxLitterSize) + 1;
        }
        return 0;
    }

    /**
     * Add offspring into available adjacent locations.
     */
    protected final void addOffspring(List<Animal> newAnimals, int births,
                                      OffspringFactory offspringFactory)
    {
        Field field = getField();
        List<Location> free = freeAdjacentLocations();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location location = free.remove(0);
            newAnimals.add(offspringFactory.create(field, location));
        }
    }

    /**
     * Check whether a mate of the same species is nearby.
     */
    protected final boolean hasAdjacentMate(Class<? extends Animal> animalClass, int radius)
    {
        for(Location where : adjacentLocations(radius)) {
            Animal mate = getObjectAt(where, animalClass);
            if(mate != null && mate.getGender() != getGender()) {
                return true;
            }
        }
        return false;
    }
}

import java.util.List;
import java.util.Random;

/**
 * A simple model of a mouse.
 * Mice age, move, eat seed, breed, and die.
 *
 * @version 2022.03.02 
 */
public class Mouse extends Animal
{
    // Characteristics shared by all mouses (class variables).

    // The age at which a mouse can start to breed.
    private static final int BREEDING_AGE = 5;
    // The age to which a mouse can live.
    private static final int MAX_AGE = 125;
    // The likelihood of a mouse breeding.
    private static final double BREEDING_PROBABILITY = 0.25;
    // The likelihood of a mouse infect by disease.
    private static final double INFECT_PROBABILITY = 0.01;
    // The maximum number of births.
    private static final int MAX_LITTER_SIZE = 10;
    // The food value of a single mouse. In effect, this is the
    // number of steps a mouse can go.
    private static final int DEFAULT_FOOD_LEVEL = 5;
    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();
    // The food value of a single mouse. 
    private static final int FOOD_VALUE = 5;

    // The mouse infected by deisease.
    // 0 - not infect, 1-3 degree of infection.
    private int infect;
    // chance of a mice to recover or deteriorate from disease.
    private static final double recover_probability = 0.3 ;
    private static final double deteriorate_probability = 0.15 ;
    /**
     * Create a new mouse. A mouse may be created with age
     * zero (a new born) or with a random age.
     * 
     * @param randomAge If true, the mouse will have a random age.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Mouse(boolean randomAge, Field field, Location location)
    {
        super(field, location);
        initializeAge(randomAge, MAX_AGE);
        initializeFoodLevel(randomAge, DEFAULT_FOOD_LEVEL, DEFAULT_FOOD_LEVEL);
    }

    /**
     * This is what the mouse does most of the time - it runs 
     * around. Sometimes it will breed or die of old age.
     * @param newMice A list to return newly born mouse.
     * @param step The current simulation step.
     */
    public void act(List<Animal> newMice, SimulationStep step)
    {
        incrementAge(MAX_AGE);
        updateBurnStatus(step.getWeather());
        checkInfectLevel();
        if(isAlive()) {
            // Infected mouse will spread the disease to other mouse.
            if (getInfected() != 0){
                forEachAdjacent(Mouse.class, 1, mouse -> {
                    if(mouse.getInfected() == 0) {
                        mouse.infect();
                    }
                });
                diseaseRecover();
            }
            else {
                giveBirth(newMice);    
                infect();
            }

            // Move towards a source of food if found.
            Location newLocation = findFood();

            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = freeAdjacentLocation();
            }

            moveToOrDie(newLocation);
        }                    
    }

    /**
     * Check whether or not this mouse is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newMice A list to return newly born mouse.
     */
    private void giveBirth(List<Animal> newMice)
    {
        addOffspring(newMice, breed(), (field, location) -> new Mouse(false, field, location));
    }

    /**
     * Look for grass adjacent to the current location.
     * Only the first seed (belong to grass) will be located.
     * @return Where food was found, or null if it wasn't.
     */
    private Location findFood()
    {
        return findAdjacentLocation(Grass.class, 1, grass -> {
            if(grass.isAlive()) {
                changeFoodLevel(2);
                return true;
            }
            return false;
        });
    }

    /**
     * Generate a number representing the number of births,
     * if it can breed.
     * @return The number of births (may be zero).
     */
    private int breed()
    {
        return calculateBirths(BREEDING_AGE, BREEDING_PROBABILITY, MAX_LITTER_SIZE);
    }

    /**
     * @return true if the mouse is infected by disease, false otherwise.
     */
    private int getInfected()
    {
        return infect;
    }

    /**
     * A mouse can be infected by disease.
     */
    private void infect()
    {
        if(rand.nextDouble() <= INFECT_PROBABILITY) {
            infect = 1;
        }        
    }
    /**
     * mouse will die from disease when the infect indicator reach 3.
     */
    private void checkInfectLevel()
    {
        if(infect == 3) {
            setDead();
        }
    }

    /**
     * A mouse can recover or deteriorate from disease
     */
    private void diseaseRecover()
    {
        if(rand.nextDouble() <= deteriorate_probability) {
            infect ++ ;
        }  
        else if (rand.nextDouble() <= recover_probability) {
            infect -- ;
        }  
    }

    /**
     * @return mouse's food value.
     */
    public int foodValue()
    {
        return FOOD_VALUE;
    }
}

