 14	    // The age at which a mouse can start to breed.
 15	    private static final int BREEDING_AGE = 5;
 16	    // The age to which a mouse can live.
 17	    private static final int MAX_AGE = 125;
 18	    // The likelihood of a mouse breeding.
 19	    private static final double BREEDING_PROBABILITY = 0.25;
 20	    // The likelihood of a mouse infect by disease.
 21	    private static final double INFECT_PROBABILITY = 0.01;
 22	    // The maximum number of births.
 23	    private static final int MAX_LITTER_SIZE = 10;
 24	    // The food value of a single mouse. In effect, this is the
 25	    // number of steps a mouse can go.
 26	    private static final int DEFAULT_FOOD_LEVEL = 5;
 27	    // A shared random number generator to control breeding.
 28	    private static final Random rand = Randomizer.getRandom();
 29	    // The food value of a single mouse. 
 30	    private static final int FOOD_VALUE = 5;
 31	    
 32	    // The mouse infected by deisease.
 33	    // 0 - not infect, 1-3 degree of infection.
 34	    private int infect;
 35	    // chance of a mice to recover or deteriorate from disease.
 36	    private static final double recover_probability = 0.3 ;
 37	    private static final double deteriorate_probability = 0.15 ;
 38	    /**
 39	     * Create a new mouse. A mouse may be created with age
 40	     * zero (a new born) or with a random age.
 41	     * 
 42	     * @param randomAge If true, the mouse will have a random age.
 43	     * @param field The field currently occupied.
