 45	     */
 46	    public Mouse(boolean randomAge, Field field, Location location)
 47	    {
 48	        super(field, location);
 49	        initializeAge(randomAge, MAX_AGE);
 50	        initializeFoodLevel(randomAge, DEFAULT_FOOD_LEVEL, DEFAULT_FOOD_LEVEL);
 51	    }
 52	    
 53	    /**
 54	     * This is what the mouse does most of the time - it runs 
 55	     * around. Sometimes it will breed or die of old age.
 56	     * @param newMice A list to return newly born mouse.
 57	     * @param step The current simulation step.
 58	     */
