 71	    /**
 72	     * Check whether or not this mouse is to give birth at this step.
 73	     * New births will be made into free adjacent locations.
 74	     * @param newMice A list to return newly born mouse.
 75	     */
 76	    @Override
 77	    protected void handleAliveStep(List<Animal> newMice, SimulationStep step)
 78	    {
 79	        if(getInfected() != 0) {
 80	            forEachAdjacent(Mouse.class, 1, mouse -> {
 81	                if(mouse.getInfected() == 0) {
 82	                    mouse.infect();
 83	                }
 84	            });
 85	            diseaseRecover();
 86	        }
 87	        else {
 88	            addOffspring(newMice, breed(), (field, location) -> new Mouse(false, field, location));
 89	            infect();
 90	        }
 91	    }
