133	    /**
134	     * A mouse can be infected by disease.
135	     */
136	    private void infect()
137	    {
138	        if(rand.nextDouble() <= INFECT_PROBABILITY) {
139	            infect = 1;
140	        }        
141	    }
142	    /**
143	     * mouse will die from disease when the infect indicator reach 3.
144	     */
145	    private void checkInfectLevel()
