152	    /**
153	     * A mouse can recover or deteriorate from disease
154	     */
155	    private void diseaseRecover()
156	    {
157	        if(rand.nextDouble() <= deteriorate_probability) {
158	            infect ++ ;
159	        }  
160	        else if (rand.nextDouble() <= recover_probability) {
161	            infect -- ;
162	        }  
163	    }
